class Solution:
    def nextBadge(self, code: str) -> str:
        count = [0] * 10
        for ch in code:
            count[ord(ch) - 48] += 1
        buf = []
        def build():
            if len(buf) == len(code):
                s = "".join(buf)
                return s if s > code else None
            for d in range(10):
                if count[d]:
                    count[d] -= 1
                    buf.append(chr(48 + d))
                    found = build()
                    buf.pop()
                    count[d] += 1
                    if found:
                        return found
            return None
        return build() or ""

