class Solution {
    private int[] count = new int[10];
    private char[] buf;
    private String code;

    public String nextBadge(String code) {
        this.code = code;
        buf = new char[code.length()];
        for (char ch : code.toCharArray()) count[ch - '0']++;
        String found = build(0);
        return found == null ? "" : found;
    }

    private String build(int pos) {
        if (pos == buf.length) {
            String s = new String(buf);
            return s.compareTo(code) > 0 ? s : null;
        }
        for (int d = 0; d < 10; d++) {
            if (count[d] == 0) continue;
            count[d]--;
            buf[pos] = (char) ('0' + d);
            String found = build(pos + 1);
            count[d]++;
            if (found != null) return found;
        }
        return null;
    }
}

