static int count[10];
static char* buf;
static const char* target;
static int len;

static bool build(int pos) {
    if (pos == len) return strcmp(buf, target) > 0;
    for (int d = 0; d < 10; d++) {
        if (!count[d]) continue;
        count[d]--;
        buf[pos] = '0' + d;
        bool found = build(pos + 1);
        count[d]++;
        if (found) return true;
    }
    return false;
}

char* nextBadge(char* code) {
    len = strlen(code);
    target = code;
    buf = calloc(len + 1, 1);
    memset(count, 0, sizeof count);
    for (int i = 0; i < len; i++) count[code[i] - '0']++;
    if (!build(0)) buf[0] = '\0';
    return buf;
}

