class Solution:
    def nextBadge(self, code: str) -> str:
        d = list(code)
        i = len(d) - 2
        while i >= 0 and d[i] >= d[i + 1]:
            i -= 1
        if i < 0:
            return ""
        j = min((k for k in range(i + 1, len(d)) if d[k] > d[i]), key=lambda k: d[k])
        d[i], d[j] = d[j], d[i]
        d[i + 1:] = sorted(d[i + 1:])
        return "".join(d)

