class Solution {
    public String nextBadge(String code) {
        char[] d = code.toCharArray();
        int i = d.length - 2;
        while (i >= 0 && d[i] >= d[i + 1]) i--;
        if (i < 0) return "";
        int j = -1;
        for (int k = i + 1; k < d.length; k++)
            if (d[k] > d[i] && (j < 0 || d[k] < d[j])) j = k;
        char t = d[i]; d[i] = d[j]; d[j] = t;
        Arrays.sort(d, i + 1, d.length);
        return new String(d);
    }
}

