char* nextBadge(char* code) {
    int n = strlen(code);
    char* d = malloc(n + 1);
    memcpy(d, code, n + 1);
    int i = n - 2;
    while (i >= 0 && d[i] >= d[i + 1]) i--;
    if (i < 0) { d[0] = '\0'; return d; }
    int j = -1;
    for (int k = i + 1; k < n; k++)
        if (d[k] > d[i] && (j < 0 || d[k] < d[j])) j = k;
    char t = d[i]; d[i] = d[j]; d[j] = t;
    qsort(d + i + 1, n - i - 1, 1, cmpChar);
    return d;
}

